mapper.select:
SELECT sod.shipment_id, item.item_name, item.item_no, sku.id AS skuId, sku.sku_name, sku.sku_no, sod.quantity, item.unit, IF(sod.storage_shelf IS NULL OR sod.storage_shelf = '', '-', sod.storage_shelf) AS storage_shelf, sod.unit_price, (sod.quantity * sod.unit_price) AS totalPrice FROM wms_shipment_order_detail sod INNER JOIN wms_item_sku sku ON sku.id = sod.sku_id INNER JOIN wms_item item ON item.id = sku.item_id WHERE sod.shipment_id = #{dto.shipmentId}
AND ( item.item_name LIKE CONCAT('%', #{dto.item}, '%') OR item.item_no LIKE CONCAT('%', #{dto.item}, '%') )
AND ( sku.sku_name LIKE CONCAT('%', #{dto.sku}, '%') OR sku.sku_no LIKE CONCAT('%', #{dto.sku}, '%') )
